@OptIn(ExperimentalMaterial3Api::class) @Composable fun ExploreScreen(onJob:(Long)->Unit,onProfile:()->Unit){var q by remember{mutableStateOf("")};var category by remember{mutableStateOf("All Jobs")};var sheet by remember{mutableStateOf(false)};var remote by remember{mutableStateOf(false)};var saved by remember{mutableStateOf(setOf<Long>())};val jobs=demoJobs.filter{(category=="All Jobs"||it.category==category)&&(!remote||it.remote)&&(it.title.contains(q,true)||it.company.contains(q,true))};if(sheet) FilterSheet({sheet=false},{remote=it;sheet=false});Scaffold(containerColor=CardBackground,topBar={TopAppBar(title={Text("SkillBridge",fontWeight=FontWeight.ExtraBold,color=BluePrimary)},actions={BadgedBox({Badge{Text("3")}}){IconButton({}){Icon(Icons.Default.Notifications,null)}}})},bottomBar={NavigationBar{NavigationBarItem(true,{}, {Icon(Icons.Default.Explore,null)},{Text("Explore")});NavigationBarItem(false,{}, {Icon(Icons.Default.Assignment,null)},{Text("Applied")});NavigationBarItem(false,onProfile,{Icon(Icons.Default.Person,null)},{Text("Profile")})}}){pad->LazyColumn(Modifier.fillMaxSize().padding(pad),contentPadding=PaddingValues(bottom=24.dp),verticalArrangement=Arrangement.spacedBy(14.dp)){item{LocationCard()};item{SearchBar(q,{q=it},{sheet=true})};item{LazyRow(contentPadding=PaddingValues(horizontal=16.dp),horizontalArrangement=Arrangement.spacedBy(8.dp)){items(listOf("All Jobs","Design","Coding","Marketing","Writing")){c->FilterChip(selected=category==c,onClick={category=c},label={Text(c)})}}};item{Text("Nearby opportunities",Modifier.padding(horizontal=16.dp),style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.Bold)};if(jobs.isEmpty())item{EmptyJobs()};items(jobs,key={it.id}){job->JobCard(job,saved.contains(job.id),{onJob(job.id)},{saved=if(saved.contains(job.id))saved-job.id else saved+job.id})}}}}
@Composable private fun LocationCard(){val pulse=rememberInfiniteTransition(label="pin").animateFloat(1f,1.1f,infiniteRepeatable(tween(700),RepeatMode.Reverse),label="p");Card(Modifier.fillMaxWidth().padding(horizontal=16.dp),shape=RoundedCornerShape(16.dp),colors=CardDefaults.cardColors(IconBgBlue)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.LocationOn,null,Modifier.scale(pulse.value),BluePrimary);Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text("YOUR LOCATION",style=MaterialTheme.typography.labelSmall,color=TextGray);Text("Near Stanford University",fontWeight=FontWeight.Bold)};Icon(Icons.Default.Edit,null,tint=TextGray)}}
@Composable private fun SearchBar(q:String,onQ:(String)->Unit,onFilter:()->Unit){OutlinedTextField(q,onQ,Modifier.fillMaxWidth().padding(horizontal=16.dp),placeholder={Text("Search jobs, skills…")},leadingIcon={Icon(Icons.Default.Search,null)},trailingIcon={IconButton(onFilter){Icon(Icons.Default.Tune,null)}},shape=RoundedCornerShape(28.dp),singleLine=true,colors=OutlinedTextFieldDefaults.colors(unfocusedBorderColor=Color.Transparent,focusedBorderColor=BluePrimary,unfocusedContainerColor=Color.White,focusedContainerColor=Color.White))}
@Composable fun JobCard(j:Job,saved:Boolean,onClick:()->Unit,onSave:()->Unit){val h=LocalHapticFeedback.current;var pressed by remember{mutableStateOf(false)};Card(Modifier.fillMaxWidth().padding(horizontal=16.dp).scale(if(pressed).98f else 1f).clickable{pressed=true;onClick()},shape=RoundedCornerShape(16.dp),elevation=CardDefaults.cardElevation(2.dp)){Column(Modifier.padding(16.dp)){Row(verticalAlignment=Alignment.CenterVertically){Surface(Modifier.size(45.dp),shape=RoundedCornerShape(13.dp),color=GradientStart){Box(contentAlignment=Alignment.Center){Text(j.initials,color=Color.White,fontWeight=FontWeight.Bold)}};Spacer(Modifier.width(12.dp));Column(Modifier.weight(1f)){Text(j.title,fontWeight=FontWeight.Bold);Row{Text(j.company,color=TextGray);Icon(Icons.Default.Verified,null,Modifier.padding(start=4.dp).size(16.dp),SuccessGreen)}};IconButton({h.performHapticFeedback(HapticFeedbackType.LongPress);onSave()}){Icon(if(saved)Icons.Default.Bookmark else Icons.Default.BookmarkBorder,null,tint=if(saved)BluePrimary else TextGray)}};Spacer(Modifier.height(12.dp));Row{AssistChip({}, {Icon(Icons.Default.Payments,null,Modifier.size(16.dp))},{Text("$${j.pay}/hr")});Spacer(Modifier.width(8.dp));AssistChip({}, {Icon(Icons.Default.NearMe,null,Modifier.size(16.dp))},{Text("${j.distance} mi")});if(j.fresh){Spacer(Modifier.width(8.dp));Surface(color=Color(0xFFDCFCE7),shape=RoundedCornerShape(6.dp)){Text("NEW",Modifier.padding(7.dp,3.dp),color=SuccessGreen,style=MaterialTheme.typography.labelSmall,fontWeight=FontWeight.Bold)}}};Spacer(Modifier.height(10.dp));Surface(color=if(j.category=="Coding")Color(0xFFEDE9FE) else Color(0xFFDBEAFE),shape=RoundedCornerShape(8.dp)){Text(j.category,Modifier.padding(9.dp,5.dp),color=BluePrimary,style=MaterialTheme.typography.labelMedium)}}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun FilterSheet(onDismiss:()->Unit,onApply:(Boolean)->Unit){var r by remember{mutableStateOf(false)};ModalBottomSheet(onDismissRequest=onDismiss){Column(Modifier.padding(24.dp).navigationBarsPadding()){Text("Filter opportunities",style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Spacer(Modifier.height(16.dp));Text("Pay range: $10 — $100 / hr");Slider(value=50f,onValueChange={},valueRange=10f..100f);Text("Distance: 0.5 — 10 miles");Slider(value=4f,onValueChange={},valueRange=.5f..10f);Row(verticalAlignment=Alignment.CenterVertically){Text("Remote only",Modifier.weight(1f));Switch(r,{r=it})};Spacer(Modifier.height(18.dp));Button({onApply(r)},Modifier.fillMaxWidth()){Text("Show jobs")}}}}
